from pathlib import Path
import subprocess,json,shutil,os,base64
P=Path(__file__).resolve().parent.parent
(P/'assets/sky-data.json').write_text(json.dumps({'url':'data:image/jpeg;base64,'+base64.b64encode((P/'assets/cloud-sky-4k.jpg').read_bytes()).decode()}))
es=os.environ.get('ESBUILD_BIN') or shutil.which('esbuild')
if not es:
    es=str(next((Path.home()/'.npm/_npx').glob('*/node_modules/esbuild/bin/esbuild')))
subprocess.run([es,'scripts/scene.js','--bundle','--format=iife','--minify','--alias:three='+str(P/'vendor/three/build/three.module.js'),'--outfile=assets/scene.bundle.js'],cwd=P,check=True)
css='*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#4e99c9}#root{position:relative;width:1920px;height:1080px;overflow:hidden}.clip{position:absolute;inset:0}canvas{position:absolute;inset:0;display:block;width:100%;height:100%}'
timeline="const clock={_t:0,get t(){return this._t},set t(v){this._t=v;if(window.renderAt)window.renderAt(v)}};const tl=gsap.timeline({paused:true});tl.to(clock,{t:5,duration:5,ease:'none'},0);window.__timelines={'tsinghua-mem-05-cloud':tl};"
base='''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>05 · 清华MEM · 蓝天云启</title><style>CSS</style></head><body><div id="root" data-composition-id="tsinghua-mem-05-cloud" data-duration="5" data-width="1920" data-height="1080" data-fps="30"><div class="clip" id="cloud-assembly" data-start="0" data-duration="5" data-track-index="1"><canvas id="three-layer" width="1920" height="1080"></canvas></div></div><script src="assets/gsap.min.js"></script><script>TIMELINE</script><script src="assets/scene.bundle.js"></script></body></html>'''.replace('CSS',css).replace('TIMELINE',timeline)
(P/'index.html').write_text(base)
playercss='html,body{height:auto;min-height:100%;background:#142b40;color:#e2edf5;font:14px sans-serif}body{display:flex;align-items:center;flex-direction:column;padding:18px}#frame{width:min(94vw,145vh,1920px);aspect-ratio:16/9;position:relative}#root{width:1920px;height:1080px;transform-origin:top left}.controls{width:min(90vw,850px);display:flex;gap:12px;padding:16px 0;align-items:center}button{background:#244962;color:#edf6ff;border:1px solid #83bdd8;border-radius:7px;padding:9px 14px;cursor:pointer}input{flex:1;accent-color:#a9e0ed}output{font:12px monospace}'
controls='<div class="controls"><button id="play">播放</button><button id="replay">重播</button><input id="scrub" type="range" aria-label="时间轴" min="0" max="5" step=".001" value="0"><output id="time">0.00 / 5</output><button id="cloud-toggle">前景云：开</button></div>'
playerjs="const root=document.getElementById('root');const frame=document.createElement('div');frame.id='frame';root.before(frame);frame.append(root);function size(){root.style.transform='scale('+frame.clientWidth/1920+')'}window.addEventListener('resize',size);size();const play=document.getElementById('play'),scrub=document.getElementById('scrub'),output=document.getElementById('time');const sync=()=>{scrub.value=tl.time();output.textContent=tl.time().toFixed(2)+' / 5';if(tl.time()>=5){tl.pause();play.textContent='播放'}};tl.eventCallback('onUpdate',sync);play.onclick=()=>{if(tl.paused()){if(tl.time()>=5)tl.time(0);tl.play();play.textContent='暂停'}else{tl.pause();play.textContent='播放'}};document.getElementById('replay').onclick=()=>{tl.time(0).play();play.textContent='暂停'};scrub.oninput=()=>{tl.pause().time(Number(scrub.value));window.renderAt(Number(scrub.value));play.textContent='播放';sync()};let foregroundOn=true;document.getElementById('cloud-toggle').onclick=()=>{foregroundOn=!foregroundOn;window.setForegroundClouds(foregroundOn);document.getElementById('cloud-toggle').textContent='前景云：'+(foregroundOn?'开':'关')};"
license_text=(P/'research/three-license.txt').read_text()
standalone=base.replace('<script src="assets/gsap.min.js"></script>','<script>'+(P/'assets/gsap.min.js').read_text()+'</script>').replace('<script src="assets/scene.bundle.js"></script>','<script>/*'+license_text+'*/'+(P/'assets/scene.bundle.js').read_text()+'</script>').replace('</head>','<style>'+playercss+'</style></head>').replace('</body>',controls+'<script>'+playerjs+'</script></body>')
(P/'deliverables/05-Blue-Sky-Cloud-Opening.html').write_text(standalone)
(P/'hyperframes.json').write_text(json.dumps({'paths':{'assets':'assets','blocks':'compositions'},'authoringSkill':'motion-graphics'},indent=2))
(P/'meta.json').write_text(json.dumps({'id':'tsinghua-mem-05-cloud','name':'05 蓝天云启'},ensure_ascii=False,indent=2))
print('Built 5-second scene and embedded offline player')
